let prior = value
extension TokenConsumer {
  mutating func atBinaryOperatorArgument() -> Bool {
    var lookahead
= self.lookahead()
    _ = lookahead.consumeModuleSelectorTokensIfPresent()
    return lookahead.at(./*c*/binaryOperator) && lookahead.peek(isAt: .comma, .rightParen, .rightSquare)
  }
}
